import 'learn_data.dart';

class LearnDataZh {
  static const List<LearnContent> contents = [
    LearnContent(title: '靠左行驶规则', icon: 'arrow_back', summary: '自行车必须靠道路左侧行驶', content: '自行车是车辆，必须在车道左侧边缘行驶。\n\n靠右行驶（逆行）非常危险，会增加正面碰撞风险，导致严重事故。\n\n有路侧带的道路也要靠左行驶。但行人专用路侧带（双白线）不可通行。', keyPoints: ['靠道路左侧边缘行驶', '靠右行驶（逆行）严禁', '路侧带也靠左行驶', '行人专用路侧带不可通行'], category: 'basic', penalty: '3个月以下有期徒刑或5万日元以下罚款', lawReference: '道路交通法第17条第4项、第18条第1项'),
    LearnContent(title: '自行车是"车辆"', icon: 'electric_bike', summary: '自行车作为轻型车辆有遵守交通规则的义务', content: '根据道路交通法，自行车被归类为"轻型车辆"。\n\n与汽车和摩托车一样，有遵守交通规则的义务，违反将受到处罚。\n\n2015年6月起，3年内因2次以上危险行为被查处的，必须参加讲习。', keyPoints: ['自行车归类为"轻型车辆"', '交通违规将受处罚', '危险行为2次需参加讲习', '与汽车适用相同规则'], category: 'basic', lawReference: '道路交通法第2条第1项第11号'),
    LearnContent(title: '人行道骑行条件', icon: 'directions_walk', summary: '自行车在人行道骑行的条件有限', content: '自行车原则上在车道行驶。人行道是行人的场所。\n\n以下情况例外允许在人行道骑行：\n①有"自行车可通行"标志\n②13岁以下儿童或70岁以上老人\n③车道状况不得已时\n\n在人行道骑行时须靠车道一侧慢行，不得妨碍行人。', keyPoints: ['原则上在车道行驶', '人行道骑行仅作为例外', '人行道上靠车道侧慢行', '对行人按铃是违规'], category: 'basic', penalty: '2万日元以下罚款', lawReference: '道路交通法第63条之4'),
    LearnContent(title: '正确的临时停车方法', icon: 'pan_tool', summary: '在停车标志处必须完全停车', content: '在有停车标志的路口，必须在停止线前完全停车。自行车也一样。\n\n完全停车是指双脚着地，车辆完全停止。\n\n2024年11月起，自行车未停车违规成为罚款（蓝色罚单）对象。', keyPoints: ['停止线前完全停车', '双脚着地', '左右安全确认', '视野不好的地方特别注意'], category: 'intersection', penalty: '罚款5,000日元起（2024年11月起蓝色罚单对象）', lawReference: '道路交通法第43条'),
    LearnContent(title: '自行车信号规则', icon: 'traffic', summary: '自行车遵从车辆用信号', content: '自行车是"车辆"。原则上遵从车辆用信号灯。\n\n有"行人·自行车专用"信号灯时，遵从该信号。\n\n右转时采用两段式右转。闯红灯将被罚款。', keyPoints: ['遵从车辆用信号', '有"行人·自行车专用"信号时遵从', '右转用两段式', '绿灯也要确认安全'], category: 'intersection', penalty: '罚款6,000日元起（闯红灯）', lawReference: '道路交通法第7条'),
    LearnContent(title: '两段式右转方法', icon: 'turn_right', summary: '自行车右转须分两段进行', content: '自行车在路口右转时，需要两段式右转。\n\n①先沿路口左侧直行\n②过路口后转向右方\n③对面信号变绿后直行\n\n小路口也适用同样规则。', keyPoints: ['右转必须分两段', '先直行再转向', '遵从对面信号', '小路口规则相同'], category: 'intersection', lawReference: '道路交通法第34条第3项'),
    LearnContent(title: '人行横道规则', icon: 'directions_walk', summary: '彻底贯彻行人优先', content: '人行横道是为行人设置的。\n\n自行车过人行横道时，原则上应下车步行。\n\n无信号人行横道有行人时必须临时停车。', keyPoints: ['人行横道行人最优先', '下车步行为原则', '有行人必须停车', '有自行车横道时使用'], category: 'intersection', penalty: '罚款6,000日元起（妨碍行人）', lawReference: '道路交通法第38条'),
    LearnContent(title: '单行道规则', icon: 'arrow_forward', summary: '确认"自行车除外"辅助标志', content: '单行道只能按指定方向通行。\n\n有"自行车除外"辅助标志时，自行车可逆向通行。\n\n无辅助标志的单行道逆行属于违规。', keyPoints: ['单行道也适用于自行车', '确认"自行车除外"辅助标志', '无辅助标志则禁止逆行', '违反将受处罚'], category: 'road', penalty: '3个月以下有期徒刑或5万日元以下罚款', lawReference: '道路交通法第8条第1项'),
    LearnContent(title: '自行车道骑行方法', icon: 'compare_arrows', summary: '正确使用自行车专用通行带', content: '有自行车专用通行带的道路，自行车必须在该通行带内行驶。\n\n车道内也以靠左行驶为基本。严禁逆行。', keyPoints: ['有自行车道就在那里行驶', '车道内也靠左行驶', '严禁逆行', '安全避开违停车辆'], category: 'road', lawReference: '道路交通法第20条'),
    LearnContent(title: '夜间骑行规则', icon: 'nightlight', summary: '前灯和反光板是必须的', content: '夜间（日落到日出）骑行必须开启前灯。\n\n还需要尾灯或反光板。前灯须为白色或淡黄色，能照亮10m前方。', keyPoints: ['前灯点亮是义务', '需要尾灯或反光板', '能照亮10m前方', '推荐反光材料和亮色衣服'], category: 'equipment', penalty: '5万日元以下罚款', lawReference: '道路交通法第52条、第63条之9'),
    LearnContent(title: '头盔佩戴努力义务', icon: 'sports_motorsports', summary: '2023年4月起全年龄努力义务化', content: '2023年4月1日起，所有自行车使用者的头盔佩戴成为努力义务。\n\n自行车事故死亡原因约60%为头部损伤。假人实验确认，佩戴头盔可大幅减轻头部冲击。\n\n请选择带有以下标志的产品：SG·JCF·CE(EN1078)·JIS', keyPoints: ['2023年4月起全年龄努力义务', '事故死亡原因约60%为头部损伤', '选择SG·JCF·CE·JIS标志产品', '尺寸合适的头盔很重要'], category: 'equipment', lawReference: '道路交通法第63条之11(1)(2)(3)', source: '出处：大阪市《自行车规则手册》(2025年9月发行)独立重新编写'),
    LearnContent(title: '刹车维护义务', icon: 'build', summary: '前后刹车的装备和维护是骑行者的义务', content: '自行车必须在前后轮都装备刹车。\n\n无刹车自行车在公路上骑行是违法的。', keyPoints: ['前后刹车都是必须的', '无刹车自行车违法', '定期检查维护重要', '雨天注意刹车效果'], category: 'equipment', penalty: '5万日元以下罚款（刹车不良）', lawReference: '道路交通法第63条之9'),
    LearnContent(title: '禁止酒后骑车', icon: 'local_bar', summary: '自行车酒驾也是严重犯罪', content: '自行车也是车辆。酒后骑车被法律严格禁止。\n\n2024年11月法律修订后，"酒气带驾驶"也新设了处罚。\n\n【处罚区分】\n· 酒气带驾驶：3年以下拘禁刑或50万日元以下罚款\n· 醉酒驾驶：5年以下拘禁刑或100万日元以下罚款\n\n提供自行车或酒类给酒驾者也会被处罚。\n\n"只喝了一点"不是借口。喝了酒绝对不骑车。', keyPoints: ['2024年11月起酒气带驾驶也新设处罚', '醉酒驾驶：5年以下徒刑或100万日元以下罚款', '提供自行车/酒类者也受罚', '少量也不能骑'], category: 'prohibition', penalty: '酒气带:3年/50万 / 醉酒:5年/100万', lawReference: '道路交通法第65条第1项', source: '出处：大阪市《自行车规则手册》(2025年9月发行)独立重新编写'),
    LearnContent(title: '禁止骑车使用手机', icon: 'phone_android', summary: '2024年11月起处罚大幅加强', content: '骑车时操作智能手机非常危险。\n\n2024年11月1日起处罚大幅加强。\n\n手持手机：6个月以下徒刑或10万日元以下罚款', keyPoints: ['2024年11月起处罚大幅加强', '手持手机：徒刑6个月或罚款10万日元', '造成危险时处罚更重', '操作必须停车后进行'], category: 'prohibition', penalty: '6个月以下有期徒刑或10万日元以下罚款', lawReference: '道路交通法第71条第5号之5（2024年修订）'),
    LearnContent(title: '耳机使用限制', icon: 'headphones', summary: '听不到周围声音的状态下骑行被禁止', content: '许多都道府县条例禁止使用耳机等导致听不到安全驾驶所需声音的状态下骑行。', keyPoints: ['听不到周围声音属于违规', '听不到急救车警笛很危险', '单耳耳机也可能被禁止', '骨传导耳机也要注意音量'], category: 'prohibition', penalty: '5万日元以下罚款（都道府县条例）', lawReference: '各都道府县道路交通规则'),
    LearnContent(title: '禁止打伞骑车', icon: 'umbrella', summary: '单手骑行是重大事故的原因', content: '打伞骑自行车在许多都道府县条例中被禁止。\n\n雨天请穿雨衣或雨披。', keyPoints: ['打伞骑车被禁止', '推荐穿雨衣', '伞架也可能被禁止', '雨天要特别谨慎'], category: 'prohibition', penalty: '5万日元以下罚款', lawReference: '各都道府县道路交通规则'),
    LearnContent(title: '禁止并排骑行', icon: 'people', summary: '自行车并排骑行原则上被禁止', content: '自行车原则上禁止并排骑行。\n\n仅有"可并行"标志时，允许最多2辆并排。', keyPoints: ['并排骑行原则禁止', '仅"可并行"标志处可以', '团体骑行保持纵列', '保持足够车间距'], category: 'prohibition', penalty: '2万日元以下罚款', lawReference: '道路交通法第19条'),
    LearnContent(title: '载人限制', icon: 'child_care', summary: '载人仅限搭载幼儿的情况', content: '自行车载人原则上禁止。\n\n16岁以上骑行者在幼儿座椅上搭载1名6岁以下幼儿时除外。', keyPoints: ['载人原则禁止', '幼儿座椅搭载6岁以下可以', '成人之间载人违规', '幼儿佩戴头盔很重要'], category: 'prohibition', penalty: '2万日元以下罚款', lawReference: '道路交通法第57条第2项'),
    LearnContent(title: '手势信号方法', icon: 'back_hand', summary: '转弯·停车时用手势表达意图', content: '自行车转弯或停车时，用手势向周围表达意图。\n\n右转：右臂水平伸出\n左转：左臂水平伸出\n停车：右臂向下伸出', keyPoints: ['转弯·停车时打手势', '信号在30m前（转弯时）', '安全最优先，不勉强', '手势可减少事故风险'], category: 'safety', lawReference: '道路交通法第53条'),
    LearnContent(title: '注意左转车辆卷入', icon: 'notifications', summary: '注意路口左转车辆的卷入事故', content: '路口最常见的自行车事故之一是被左转汽车卷入。\n\n不要在大型车辆左侧并排。', keyPoints: ['注意左转车辆卷入', '不在大型车辆左侧并排', '转向灯亮时不强行超车', '注意驾驶员盲区'], category: 'safety', lawReference: '道路交通法第34条'),
    LearnContent(title: '雨天·恶劣天气安全对策', icon: 'umbrella', summary: '天气不好时要比平时更谨慎', content: '雨天和强风等恶劣天气骑行比平时有更多危险。\n\n路面湿滑，刹车效果降低。穿雨衣是必须的。', keyPoints: ['路面湿滑（注意井盖等）', '刹车制动距离翻倍以上', '注意视野不良', '推车步行也是选择'], category: 'safety'),
    LearnContent(title: '自行车保险义务化', icon: 'security', summary: '大阪府已将自行车保险加入义务化', content: '自行车事故导致对方重伤时，可能被要求数千万日元的赔偿。\n\n【高额赔偿判例】\n· 约9,521万日元 — 小学生夜间与行人正面碰撞\n· 约9,266万日元 — 高中生斜穿车道撞伤行人\n· 约5,438万日元 — 闯红灯撞死行人\n\n大阪府自行车条例(2016年4月施行)已将保险加入义务化。每月数百日元即可加入。', keyPoints: ['大阪府保险加入义务化', '赔偿额超过9,500万日元的判例', '多种保险类型包括TS标志保险', '每月数百日元即可加入'], category: 'insurance', lawReference: '大阪府自行车条例第12条', source: '出处：大阪市《自行车规则手册》(2025年9月发行)独立重新编写'),
    LearnContent(title: '自行车蓝色罚单制度(2026年4月施行)', icon: 'receipt_long', summary: '自行车也引入交通违章罚款制度', content: '2026年4月起，自行车引入"蓝色罚单"制度。\n\n对象：16岁以上，100种以上违规行为，罚款与助力车相同。\n\n主要罚款：手机使用 12,000日元、闯红灯 6,000日元、未停车 5,000日元、耳机/打伞 5,000日元、双人骑 3,000日元。\n\n期限内缴纳可免刑事处罚。未缴纳将转为刑事程序。', keyPoints: ['2026年4月施行', '16岁以上·100种以上违规', '罚款与助力车相同', '未缴纳转为刑事程序'], category: 'new_law', lawReference: '道路交通法修订(自行车蓝色罚单制度)', source: '出处：大阪市《自行车规则手册》(2025年9月发行)独立重新编写'),
    LearnContent(title: '饮酒驾驶处罚新设', icon: 'local_bar', summary: '2024年11月起自行车饮酒驾驶也将受罚', content: '2024年11月法律修订为自行车"饮酒驾驶"新设了处罚。\n\n饮酒驾驶：3年以下徒刑或50万日元以下罚款', keyPoints: ['2024年11月起饮酒驾驶也受罚', '3年以下徒刑或50万日元以下罚款', '酒精检测器检查对象', '"微醺程度"也违规'], category: 'new_law', penalty: '3年以下有期徒刑或50万日元以下罚款', lawReference: '道路交通法修订（2024年11月施行）'),
    LearnContent(title: '道路种类与自行车通行区分', icon: 'compare_arrows', summary: '了解车道、人行道、自行车道的区别', content: '自行车通行的道路有几种类型：\n\n车道：原则上靠左侧行驶。\n自行车道：专用通行带，有时必须使用。\n自行车专用通行带(自行车车道)：蓝色标线区域。\n路侧带：白线分隔，行人优先。\n人行道：原则不能通行。', keyPoints: ['车道左侧是自行车基本位置', '自行车道有时有通行义务', '自行车车道原则在其内行驶', '路侧带左侧通行·行人优先'], category: 'road', lawReference: '道路交通法第17条、18、63条之3·4', source: '出处：大阪市《自行车规则手册》(2025年9月发行)独立重新编写'),
    LearnContent(title: '箭羽标记(自行车导航标记)', icon: 'arrow_forward', summary: '路面箭头指示自行车行驶方向', content: '近年道路上常见自行车标志和箭头组合的"箭羽标记"。\n\n该标记本身没有法律强制力。但作为自行车应在车道左侧行驶的视觉辅助。\n\n禁止逆箭头方向行驶。', keyPoints: ['箭羽标记指示自行车行驶位置和方向', '无法律强制力但为视觉辅助', '禁止逆箭头方向行驶', '无标记也须左侧通行'], category: 'road', source: '出处：大阪市《自行车规则手册》(2025年9月发行)独立重新编写'),
    LearnContent(title: '内轮差的危险性', icon: 'notifications', summary: '大型车辆左转时的"死角"危及生命', content: '"内轮差"是车辆转弯时前轮和后轮轨迹的偏差。车体越大偏差越大。\n\n大型车辆左转时，后轮走内侧，位于内侧的自行车有被卷入的危险。\n\n保护自己：不要在路口站在大型车左侧，大型车开左转灯时绝对不要进入其左侧。', keyPoints: ['内轮差大型车越大卷入事故原因', '路口不要站在大型车左侧', '左转灯亮时绝对不进入其左侧', '注意司机盲区'], category: 'safety', source: '出处：大阪市《自行车规则手册》(2025年9月发行)独立重新编写'),
    LearnContent(title: '事故发生时的应对', icon: 'emergency', summary: '万一发生事故时应采取的五个行动', content: '自行车事故时，法律要求采取适当措施。\n\n①停车：安全处停车防止二次事故\n②救护伤者：应急处理并拨打119\n③报警：无论大小拨打110\n④确认对方信息：姓名、地址、联系方式\n⑤联系保险公司', keyPoints: ['先安全停车防止二次事故', '救护伤者并拨打救护车', '无论大小均拨打110报警', '确认对方信息并联系保险公司'], category: 'safety', lawReference: '道路交通法第72条', source: '出处：大阪市《自行车规则手册》(2025年9月发行)独立重新编写'),
    LearnContent(title: '自行车驾驶者培训制度', icon: 'school', summary: '反复危险行为将被命令参加培训', content: '2015年6月起实施的"自行车驾驶者培训制度"，对反复危险行为的骑行者命令参加培训。\n\n条件：3年内因2次以上危险行为被开罚单\n对象16种危险行为：闯红灯、通行区分违规、未停车、刹车不良、醉酒驾驶、手机使用等\n\n培训：3小时，费用 6,150日元\n拒绝参加：5万日元以下罚款', keyPoints: ['3年内2次以上危险行为被命令培训', '对象16种危险行为', '培训3小时·费用6,150日元', '拒绝培训5万日元以下罚款'], category: 'new_law', penalty: '拒绝培训:5万日元以下罚款', lawReference: '道路交通法第108条之3之4', source: '出处：大阪市《自行车规则手册》(2025年9月发行)独立重新编写'),
    LearnContent(title: '大阪府自行车条例要点', icon: 'security', summary: '大阪独有规则 — 保险加入·安全利用的义务', content: '大阪府自2016年4月施行《促进自行车安全适当利用条例》。\n\n主要内容：\n1. 自行车保险加入义务\n2. 监护人对未成年人的安全教育努力义务\n3. 企业对员工的安全教育\n4. 自行车店的防盗登记·保险引导·安全信息提供义务\n5. 各机构协作推进安全利用', keyPoints: ['大阪府自行车保险义务化', '监护人对孩子安全教育努力义务', '企业对员工安全教育', '自行车店防盗登记·保险引导义务'], category: 'new_law', lawReference: '大阪府促进自行车安全适当利用条例', source: '出处：大阪市《自行车规则手册》(2025年9月发行)独立重新编写'),
    LearnContent(title: '防盗登记义务', icon: 'lock', summary: '购买自行车后防盗登记是必须的', content: '购买自行车后，法律规定必须进行防盗登记。\n\n登记费因都道府县不同（约500~700日元）。', keyPoints: ['防盗登记是法律义务', '登记费约500~700日元', '被盗时搜索·归还所需', '过期需重新登记'], category: 'registration', lawReference: '自行车安全利用促进法第12条'),
  ];
}
